package android.media; public class MediaTimestamp {private final long mediaTimeUs,systemNanoTime;private final float rate;public MediaTimestamp(long mediaTimeUs,long systemNanoTime,float rate){this.mediaTimeUs=mediaTimeUs;this.systemNanoTime=systemNanoTime;this.rate=rate;}public long getAnchorMediaTimeUs(){return mediaTimeUs;}public long getAnchorSystemNanoTime(){return systemNanoTime;}public long getAnchorSytemNanoTime(){return systemNanoTime;}public float getMediaClockRate(){return rate;}}